create extension if not exists pgcrypto;
create table public.packages(id uuid primary key default gen_random_uuid(),name text not null,code text not null unique,description text,created_at timestamptz not null default now());
create table public.licenses(id uuid primary key default gen_random_uuid(),key_hash text not null unique,key_prefix text not null,label text,status text not null default 'active' check(status in('active','blocked')),expires_at timestamptz,max_devices int not null default 1 check(max_devices between 1 and 100),package_id uuid references public.packages(id) on delete set null,created_at timestamptz not null default now());
create table public.devices(id uuid primary key default gen_random_uuid(),license_id uuid not null references public.licenses(id) on delete cascade,device_id text not null,app_id text not null,app_version text,status text not null default 'active' check(status in('active','revoked')),created_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),unique(license_id,device_id));
create table public.activation_events(id uuid primary key default gen_random_uuid(),event_type text not null,result text not null check(result in('success','failure')),license_id uuid references public.licenses(id) on delete set null,device_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index licenses_status_idx on public.licenses(status);create index devices_license_idx on public.devices(license_id);create index events_created_idx on public.activation_events(created_at desc);
alter table public.packages enable row level security;alter table public.licenses enable row level security;alter table public.devices enable row level security;alter table public.activation_events enable row level security;
-- No public or authenticated RLS policies: all database access is server-side using the service role.
